const visual = {
  prepare: function (input) {
    return [
      { kind: 'text', payload: '支点' },
      { kind: 'text', payload: '动力臂' },
      { kind: 'text', payload: '阻力臂' },
      { kind: 'text', payload: '动力臂 : 阻力臂 = 3 : 2' }
    ];
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var scale = Math.min(W / 800, H / 500);
    var ox = (W - 800 * scale) / 2;
    var oy = (H - 500 * scale) / 2;
    function p(x, y) { return [ox + x * scale, oy + y * scale]; }
    function line(a, b) {
      var A = p(a[0], a[1]);
      var B = p(b[0], b[1]);
      return [['M', A[0], A[1]], ['L', B[0], B[1]]];
    }
    function poly(points, close) {
      var c = [];
      for (var i = 0; i < points.length; i++) {
        var q = p(points[i][0], points[i][1]);
        c.push([i === 0 ? 'M' : 'L', q[0], q[1]]);
      }
      if (close) c.push(['Z']);
      return c;
    }
    function circle(cx, cy, r) {
      var q = p(cx, cy);
      return visualSdk.circle(q[0], q[1], r * scale);
    }
    function add(a, b, k) { return [a[0] + b[0] * k, a[1] + b[1] * k]; }
    function mid(a, b) { return [(a[0] + b[0]) / 2, (a[1] + b[1]) / 2]; }

    var P = [400, 300];
    var theta = -12 * Math.PI / 180;
    var u = [Math.cos(theta), Math.sin(theta)];
    var up = [Math.sin(theta), -Math.cos(theta)];
    var Lr = 160;
    var Le = 240;
    var left = [P[0] - Lr * u[0], P[1] - Lr * u[1]];
    var right = [P[0] + Le * u[0], P[1] + Le * u[1]];

    var dimOff = 48;
    var leftDim = add(left, up, dimOff);
    var pivotDim = add(P, up, dimOff);
    var rightDim = add(right, up, dimOff);
    var tickHalf = 6;
    var tickPoints = [
      leftDim,
      add(add(left, u, 80), up, dimOff),
      pivotDim,
      add(add(P, u, 80), up, dimOff),
      add(add(P, u, 160), up, dimOff),
      rightDim
    ];
    var dimCmds = line(leftDim, pivotDim).concat(line(pivotDim, rightDim));
    var tickCmds = [];
    for (var t = 0; t < tickPoints.length; t++) {
      var tp = tickPoints[t];
      tickCmds = tickCmds.concat(line(add(tp, up, -tickHalf), add(tp, up, tickHalf)));
    }

    var resLabelPos = add(mid(leftDim, pivotDim), up, 16);
    var effLabelPos = add(mid(pivotDim, rightDim), up, 16);

    var groundCmds = line([60, 400], [740, 400]);
    var fulcrumCmds = poly([[400, 300], [360, 400], [440, 400]], true);
    var barCmds = line(left, right);
    var highlightCmds = line(add(left, up, 3), add(right, up, 3));
    var stoneCmds = poly([[180, 400], [184, 370], [202, 345], [225, 328], [250, 324], [278, 340], [294, 362], [296, 400]], true);
    var effortShaft = line([635, 185], [635, 232]);
    var effortHead = poly([[627, 230], [643, 230], [635, 243]], true);
    var leaderCmds = line([456, 360], [412, 318]);
    var pivotCmds = circle(P[0], P[1], 6);

    return {
      schemaVersion: 1,
      sceneId: 'lever-stone',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'ground', commands: groundCmds },
        { id: 'fulcrum', commands: fulcrumCmds },
        { id: 'bar', commands: barCmds },
        { id: 'barHighlight', commands: highlightCmds },
        { id: 'stone', commands: stoneCmds },
        { id: 'effortShaft', commands: effortShaft },
        { id: 'effortHead', commands: effortHead },
        { id: 'dimLine', commands: dimCmds },
        { id: 'dimTicks', commands: tickCmds },
        { id: 'fulcrumLeader', commands: leaderCmds },
        { id: 'pivotDot', commands: pivotCmds }
      ],
      root: {
        type: 'group',
        children: [
          { type: 'path', pathId: 'ground', fill: '#8B7355', stroke: { width: 4, cap: 'round' } },
          { type: 'path', pathId: 'fulcrum', fill: '#5D4037', stroke: { width: 2, join: 'round' } },
          { type: 'path', pathId: 'bar', fill: '#8B5A2B', stroke: { width: 12, cap: 'round', join: 'round' } },
          { type: 'path', pathId: 'barHighlight', fill: '#C89B5A', stroke: { width: 3, cap: 'round' } },
          { type: 'path', pathId: 'stone', fill: '#7A7F87', stroke: { width: 2, join: 'round' } },
          { type: 'path', pathId: 'effortShaft', fill: '#C0392B', stroke: { width: 4, cap: 'round' } },
          { type: 'path', pathId: 'effortHead', fill: '#C0392B', stroke: { width: 2, join: 'round' } },
          { type: 'path', pathId: 'dimLine', fill: '#1F3A5F', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'dimTicks', fill: '#1F3A5F', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'fulcrumLeader', fill: '#5D4037', stroke: { width: 2, cap: 'round' } },
          { type: 'path', pathId: 'pivotDot', fill: '#B71C1C', stroke: { width: 2 } },
          { type: 'label', contentId: metrics[0].contentId, anchor: { x: p(468, 362)[0], y: p(468, 362)[1] }, hAlign: 'left', vAlign: 'middle', color: '#5D4037' },
          { type: 'label', contentId: metrics[1].contentId, anchor: { x: p(effLabelPos[0], effLabelPos[1])[0], y: p(effLabelPos[0], effLabelPos[1])[1] }, hAlign: 'center', vAlign: 'bottom', color: '#1F3A5F' },
          { type: 'label', contentId: metrics[2].contentId, anchor: { x: p(resLabelPos[0], resLabelPos[1])[0], y: p(resLabelPos[0], resLabelPos[1])[1] }, hAlign: 'center', vAlign: 'bottom', color: '#1F3A5F' },
          { type: 'label', contentId: metrics[3].contentId, anchor: { x: p(400, 80)[0], y: p(400, 80)[1] }, hAlign: 'center', vAlign: 'middle', color: '#1F3A5F' }
        ]
      }
    };
  }
};
